{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_Website_margin_fact_items as SELECT WEB.* ,FWD_FRT_EK ,ROUND(((FWD_FRT_EK + 30) * ((100 - \"CUSTOMER_RET%\")/100) / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)),2) AS REV_FRT_EK ,ROUND(5 / ((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100),2) PACKING ,ROUND(SALE_VALUE *(5/100),2) ADVT ,ROUND(SALE_VALUE *(7.5/100),2) COMMON ,ROUND(COALESCE((SALE_VALUE - COST),0),2) AS GROSS_MARGIN ,ROUND((COALESCE(FWD_FRT_EK,0) + COALESCE(REV_FRT_EK,0) + COALESCE(PACKING,0) + COALESCE(ADVT,0) + COALESCE(COMMON,0)),2) AS TOTAL_EXPENSES_EK ,COALESCE((GROSS_MARGIN - TOTAL_EXPENSES_EK),0) AS NET_MARGIN_EK ,ROUND((NET_MARGIN_EK/NULLIF(SALE_VALUE,0)*100),2) \"NET_MARGIN_EK%\" FROM( SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EANUPC, \'`\', \'\'), \',\', \'\')) EAN, A.SKU, A.GENDER, UPPER(A.CATEGORY_NAME) CATEGORY_NAME, A.SAP_CATEGORY, UPPER(A.TYPE) TYPE, UPPER(A.LEVEL) LEVEL, A.FLIPKART_CATEGORY CATEGORY, COALESCE(REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\'),A.ARTICLES) ARTICLE, A.LENGTH AS LENGTH_CM, A.HEIGHT AS HEIGHT_CM, A.WIDTH AS WIDTH_CM, A.WEIGHT, ROUND(COALESCE(TRY_TO_DOUBLE(A.WEIGHT),0) / 1000.0,2) AS WEIGHT_KG, ROUND(( COALESCE(TRY_TO_DOUBLE(A.LENGTH),0) * COALESCE(TRY_TO_DOUBLE(A.HEIGHT),0) * COALESCE(TRY_TO_DOUBLE(A.WIDTH),0)) / 5000.0,2) AS VOLUME_WEIGHT, CASE WHEN VOLUME_WEIGHT > WEIGHT_KG THEN VOLUME_WEIGHT ELSE WEIGHT_KG END AS CHARGEABLE_WEIGHT, 70.0 AS \"DISCOUNT_%\", CASE WHEN COALESCE(RF.\"Courier return %\", RA.\"Courier return %\") IS NULL OR COALESCE(RF.\"Courier return %\", RA.\"Courier return %\") = 0 THEN 25 ELSE ROUND(COALESCE(RF.\"Courier return %\", RA.\"Courier return %\"), 1) END AS \"COURIER_RET%\", CASE WHEN COALESCE(RF.\"Customer Return %\",RA.\"Customer Return %\") IS NULL OR COALESCE(RF.\"Customer Return %\",RA.\"Customer Return %\") = 0 THEN 11 ELSE ROUND(COALESCE(RF.\"Customer Return %\",RA.\"Customer Return %\"), 1)END AS \"CUSTOMER_RET%\", CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, ROUND(COALESCE(MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, ROUND(COALESCE(MRP,0) - (COALESCE(MRP,0) * \"DISCOUNT_%\" / 100),2) AS BILL_VALUE, CASE WHEN BILL_VALUE < 2625 THEN 5 ELSE 18 END AS \"GST_%\", ROUND((BILL_VALUE * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE, AVAILABLE_QUANTITY FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN ( SELECT \'01-FOOTWEAR\' CATEGORY_NAME ,\"TYPE 2\" TYPE ,GENDER ,\"Courier return %\" ,\"Customer Return %\" FROM MAPLEMONK.REDTAPE_WEBSITE_MARGIN_RETURN___FOOTWEAR WHERE UPPER(GENDER) != \'ALL\') RF ON UPPER(TRIM(A.CATEGORY_NAME)) = UPPER(TRIM(RF.CATEGORY_NAME)) AND UPPER(TRIM(A.TYPE)) = UPPER(TRIM(RF.TYPE)) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(RF.GENDER)) LEFT JOIN( SELECT \'02-APPARELS\' CATEGORY_NAME ,\"Sub Category\" SAP_CATEGORY ,GENDER ,\"Courier return %\" ,\"Customer Return %\" FROM MAPLEMONK.REDTAPE_WEBSITE_MARGIN_RETURN____APPARELS WHERE UPPER(GENDER) != \'ALL\') RA ON UPPER(TRIM(A.CATEGORY_NAME)) = UPPER(TRIM(RA.CATEGORY_NAME)) AND UPPER(TRIM(A.SAP_CATEGORY)) = UPPER(TRIM(RA.SAP_CATEGORY)) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(RA.GENDER)) ) WEB LEFT JOIN( SELECT \"Lower Weight\" LOWER_WEIGHT ,\"Upper Weight\" UPPER_WEIGHT ,\"Rest of India\" FWD_FRT_EK ,\"Reverse Fright\" RVS_FRT FROM MAPLEMONK.REDTAPE_WEBSITE_MARGIN_EKART ) EK ON WEB.CHARGEABLE_WEIGHT BETWEEN EK.LOWER_WEIGHT AND EK.UPPER_WEIGHT ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            